    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2d;
      --panel-2: #17213a;
      --border: rgba(255, 255, 255, 0.1);
      --text: #e7ecf7;
      --muted: #a8b2c7;
      --accent: #7c9cff;
      --accent-strong: #9cb2ff;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

